import{_ as e,o,c as t,a2 as i}from"./chunks/framework.CQdiwDJy.js";const c=JSON.parse('{"title":"多轮代理（tau goal）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/goal.md","filePath":"guide/goal.md","lastUpdated":1788601681000}'),s={name:"guide/goal.md"};function l(r,a,n,d,p,h){return o(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="多轮代理-tau-goal" tabindex="-1">多轮代理（tau goal） <a class="header-anchor" href="#多轮代理-tau-goal" aria-label="Permalink to &quot;多轮代理（tau goal）&quot;">​</a></h1><p><code>tau goal</code> 让 Tau 从&quot;单轮诊断者&quot;变成&quot;任务代理&quot;：一个意图可以跨越最多五个受审查的轮次——计划 → 执行 → 反思 → 再计划——每轮都过同一道确定性审查，provider 在每轮执行后决定&quot;做完了&quot;还是&quot;再来一轮&quot;。</p><h2 id="基本用法" tabindex="-1">基本用法 <a class="header-anchor" href="#基本用法" aria-label="Permalink to &quot;基本用法&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tau</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;把项目里所有 TODO 注释整理成一个清单文件&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tau</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;重构这段脚本&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rounds</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span></span></code></pre></div><p>轮次上限默认 3，<code>--rounds</code> 可调，硬上限 5。上限防止失控循环；每个提议中的下一轮计划都必须通过安全审查才能执行。</p><h2 id="轮次的生命周期" tabindex="-1">轮次的生命周期 <a class="header-anchor" href="#轮次的生命周期" aria-label="Permalink to &quot;轮次的生命周期&quot;">​</a></h2><ol><li><strong>round_plan</strong>：provider 产出（或反思后继续产出）一份计划，经 <code>reviewPlan()</code> 确定性审查。</li><li><strong>审批</strong>：非 low-risk 的轮次会暂停等待你的显式批准——代理模式永远不是&quot;一次性预授权&quot;。</li><li><strong>执行</strong>：通过 <code>runPlan()</code> 唯一执行通道运行，shell 步骤可随时中止（中止会杀掉整个进程组）。</li><li><strong>反思（reflect）</strong>：provider 拿到已执行轮次的输出（每轮截断至 4k 字符），回答&quot;完成（附最终答案）&quot;或&quot;继续（附下一轮计划）&quot;。反思产生的计划同样要被审查——AI 永不自我评分。</li></ol><p>轮次历史在提示里做了封顶（最近 3 轮原文、更早轮次压缩成一行），长任务不会撑爆上下文。</p><h2 id="流式思考-v0-5-0" tabindex="-1">流式思考（v0.5.0） <a class="header-anchor" href="#流式思考-v0-5-0" aria-label="Permalink to &quot;流式思考（v0.5.0）&quot;">​</a></h2><p>WebUI 的代理模式下，每一轮规划时 provider 的思考会实时显示：规划思考与反思思考分别标注在所属轮次的可折叠思考面板里。库层集成可通过 <code>runGoal</code> 的 <code>onPlanStream</code> 观察者获得带轮次标记的思考增量。</p><h2 id="没有反思能力的-provider" tabindex="-1">没有反思能力的 provider <a class="header-anchor" href="#没有反思能力的-provider" aria-label="Permalink to &quot;没有反思能力的 provider&quot;">​</a></h2><p>provider 的 <code>reflect()</code> 是可选能力。mock、openai 兼容、anthropic、gemini 已实现；ollama、deepseek、zai 暂未实现——它们会诚实地降级为单轮执行并附说明，绝不会静默假装完成。</p>`,12)])])}const g=e(s,[["render",l]]);export{c as __pageData,g as default};
